(function(E){ const x = E["exam-08"] = E["exam-08"] || {units:{}}; (x.units = x.units || {})["x08-l3"] = {"id":"x08-l3","patterns":["L3-humanities","PARA-opinion","TR-ruledout","TR-paraphrase"],"title":{"en":"Listening Part 3: planning an assignment","tr":"Listening Part 3: bir ödevi planlamak","fa":"Listening Part 3: برنامه‌ریزی یک تکلیف"},"objective":{"en":"In this lesson you will learn to follow two students as they plan an assignment: choose the two ideas that are really true, and answer single-choice questions about what each student thinks.","tr":"Bu derste bir ödevi planlayan iki öğrenciyi takip etmeyi öğreneceksin: gerçekten doğru olan iki fikri seçecek ve her öğrencinin ne düşündüğüyle ilgili tek cevaplı soruları cevaplayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را که تکلیفی را برنامه‌ریزی می‌کنند دنبال کنی: دو ایده‌ای را که واقعاً درست‌اند انتخاب کنی و به سؤال‌های تک‌جوابی درباره‌ی نظر هر دانشجو جواب بدهی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 3: planning an assignment","tr":"Listening Part 3: bir ödevi planlamak","fa":"Listening Part 3: برنامه‌ریزی یک تکلیف"},"objective":{"en":"In this lesson you will learn to follow two students as they plan an assignment: choose the two ideas that are really true, and answer single-choice questions about what each student thinks.","tr":"Bu derste bir ödevi planlayan iki öğrenciyi takip etmeyi öğreneceksin: gerçekten doğru olan iki fikri seçecek ve her öğrencinin ne düşündüğüyle ilgili tek cevaplı soruları cevaplayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را که تکلیفی را برنامه‌ریزی می‌کنند دنبال کنی: دو ایده‌ای را که واقعاً درست‌اند انتخاب کنی و به سؤال‌های تک‌جوابی درباره‌ی نظر هر دانشجو جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Options","tr":"Seçenek","fa":"گزینه"},"value":"A-E / A-C"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: notes in lectures","tr":"Bu sınav: derste not almak","fa":"این آزمون: یادداشت‌برداری در کلاس"},"intro":{"en":"Part 3 is a discussion between students, sometimes with a tutor. Humanities and education topics, such as study habits, are among the most frequent. Listen for opinions, not just facts.","tr":"Part 3, öğrenciler arasında, bazen bir hocayla yapılan bir tartışmadır. Çalışma alışkanlıkları gibi beşerî bilimler ve eğitim konuları en sık çıkanlardandır. Yalnızca bilgileri değil, görüşleri de dinle.","fa":"Part 3 بحثی بین دانشجوهاست، گاهی همراه یک استاد. موضوع‌های علوم انسانی و آموزش، مثل عادت‌های مطالعه، از پرتکرارترین‌ها هستند. فقط به واقعیت‌ها نه، به نظرها هم گوش بده."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x08-l3-ctx","exam":true,"patterns":["L3-humanities","PARA-opinion"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Two students plan an assignment on study skills","tr":"İki öğrenci çalışma becerileri üzerine bir ödev planlıyor","fa":"دو دانشجو تکلیفی درباره‌ی مهارت‌های مطالعه برنامه‌ریزی می‌کنند"},"asks":{"en":"Two students react to an article they read, decide what to put in their assignment, and then give their opinions on several study habits. Most questions ask what one speaker thinks, or what they both agree on.","tr":"İki öğrenci okudukları bir makaleye tepki veriyor, ödevlerine ne koyacaklarına karar veriyor ve sonra birkaç çalışma alışkanlığı hakkında görüş bildiriyor. Soruların çoğu bir konuşanın ne düşündüğünü ya da ikisinin neyde anlaştığını sorar.","fa":"دو دانشجو به مقاله‌ای که خوانده‌اند واکنش نشان می‌دهند، تصمیم می‌گیرند چه چیزی در تکلیفشان بیاورند و بعد درباره‌ی چند عادت مطالعه نظر می‌دهند. بیشتر سؤال‌ها می‌پرسند یکی از گوینده‌ها چه فکر می‌کند یا هر دو روی چه چیزی توافق دارند."},"fields":["What surprised them","What to include","Their opinions","What they will do next"],"words":[{"a":"surprising","b":"I’d have bet on the opposite / I hadn’t expected","tr":"şaşırtıcı","fa":"غافلگیرکننده"},{"a":"obvious","b":"we all knew that / nobody needs a study to tell them","tr":"apaçık","fa":"بدیهی"},{"a":"not practical","b":"that takes weeks / we’d never get anyone","tr":"uygulanabilir değil","fa":"عملی نیست"},{"a":"include","b":"put in / that would give it a structure","tr":"dahil etmek","fa":"گنجاندن"},{"a":"leave out","b":"I’d drop / they don’t tell us anything","tr":"çıkarmak","fa":"کنار گذاشتن"},{"a":"the main reason","b":"I don’t think that’s the main thing / what really happens is","tr":"asıl neden","fa":"دلیل اصلی"},{"a":"difficult to understand later","b":"I couldn’t follow them afterwards","tr":"sonradan anlaşılması zor","fa":"بعداً سخت فهمیده می‌شود"},{"a":"the most important skill","b":"what matters most / the real skill is","tr":"en önemli beceri","fa":"مهم‌ترین مهارت"},{"a":"too general","b":"it could be about anything / no detail","tr":"fazla genel","fa":"خیلی کلی"},{"a":"revise","b":"go back over before an exam","tr":"tekrar etmek","fa":"مرور کردن"},{"a":"divide the work","b":"you take this, I’ll take that","tr":"işi bölüşmek","fa":"کار را تقسیم کردن"},{"a":"agree","b":"exactly what I thought / fair enough","tr":"katılmak","fa":"موافق بودن"}],"traps":[{"en":"A reason is offered and then corrected: \"Some do, but I don’t think that’s the main thing.\" The answer is the reason that follows.","tr":"Bir neden öne sürülüp düzeltilir: \"Bazıları öyle yapıyor ama asıl mesele bu değil bence.\" Cevap ardından gelen nedendir.","fa":"دلیلی گفته و بعد اصلاح می‌شود: «بعضی‌ها این کار را می‌کنند، اما فکر نمی‌کنم موضوع اصلی این باشد». جواب دلیلی است که بعدش می‌آید."},{"en":"A good point about something comes before the problem: \"They were quick to draw... The trouble was afterwards.\" The question asks about the problem.","tr":"Bir şeyin iyi yanı sorundan önce gelir: \"Çizmesi hızlıydı... Sorun sonradan çıktı.\" Soru sorunu soruyor.","fa":"نکته‌ی خوبِ یک چیز قبل از مشکل می‌آید: «کشیدنشان سریع بود... مشکل بعدش بود». سؤال درباره‌ی مشکل است."},{"en":"One student suggests a plan and the other gives a reason it cannot work. Only plans that survive count.","tr":"Bir öğrenci bir plan önerir, diğeri işe yaramayacağının nedenini söyler. Yalnızca ayakta kalan planlar sayılır.","fa":"یک دانشجو برنامه‌ای پیشنهاد می‌کند و دیگری دلیل می‌آورد که چرا عملی نیست. فقط برنامه‌هایی حساب‌اند که سر جایشان می‌مانند."}],"example":{"lines":[["Student A","Shall we ask the librarian for help?"],["Student B","She’s on holiday this week. Let’s just ask the other group what they did."],["Student A","Good idea."]],"item":"What will the students do? A ask the librarian  B ask another group","answer":"B","why":{"en":"The librarian is suggested but is away. They agree to ask the other group.","tr":"Kütüphaneci öneriliyor ama izinde. Diğer gruba sormakta anlaşıyorlar.","fa":"کتابدار پیشنهاد می‌شود، اما در مرخصی است. توافق می‌کنند از گروه دیگر بپرسند."}}},{"id":"L3-edu","ctx":["L3-edu","L3-humanities"],"title":{"en":"Study skills, placements and careers","tr":"Çalışma becerileri, stajlar ve kariyer","fa":"مهارت مطالعه، کارآموزی و مسیر شغلی"},"asks":{"en":"Two students, sometimes with a tutor, plan or review a project on a work placement, teaching practice, a library or career plans. Questions ask what they decide, what they think of a source or a method, what went wrong and what they will do next.","tr":"İki öğrenci, bazen bir hocayla, bir staj, öğretmenlik uygulaması, bir kütüphane ya da kariyer planları üzerine bir projeyi planlar ya da değerlendirir. Sorular neye karar verdiklerini, bir kaynak ya da yöntem hakkında ne düşündüklerini, neyin ters gittiğini ve sırada ne yapacaklarını sorar.","fa":"دو دانشجو، گاهی با یک استاد، پروژه‌ای درباره‌ی یک کارآموزی، تمرین تدریس، یک کتابخانه یا برنامه‌های شغلی را برنامه‌ریزی یا بررسی می‌کنند. سؤال‌ها می‌پرسند به چه تصمیمی می‌رسند، درباره‌ی یک منبع یا روش چه فکر می‌کنند، چه چیزی خراب شد و قدم بعدی‌شان چیست."},"fields":["What did the student find most useful about the placement?","What does the tutor advise?","Which TWO skills does the student want to improve?","What is the student’s plan after the course?"],"words":[{"a":"placement","b":"time working in a real job during the course","tr":"staj","fa":"کارآموزی"},{"a":"tutor","b":"the teacher who supervises you","tr":"danışman hoca","fa":"استاد راهنما"},{"a":"feedback","b":"comments on your work","tr":"geri bildirim","fa":"بازخورد"},{"a":"assignment","b":"the piece of written work","tr":"ödev","fa":"تکلیف"},{"a":"deadline","b":"the date you must hand it in","tr":"son teslim tarihi","fa":"مهلت تحویل"},{"a":"reflect on","b":"think about what you learned","tr":"üzerine düşünmek","fa":"تأمل کردن درباره‌ی"},{"a":"case study","b":"one real example in detail","tr":"vaka çalışması","fa":"مطالعه‌ی موردی"},{"a":"confidence","b":"believing you can do it","tr":"özgüven","fa":"اعتمادبه‌نفس"},{"a":"time management","b":"organising your hours","tr":"zaman yönetimi","fa":"مدیریت زمان"},{"a":"supervisor","b":"the person in charge of you at work","tr":"iş yerindeki sorumlu","fa":"سرپرست"},{"a":"career","b":"the job you want long-term","tr":"kariyer","fa":"مسیر شغلی"},{"a":"appendix","b":"extra pages at the end of a report","tr":"ek","fa":"پیوست"}],"traps":[{"en":"Tutor and student can disagree. The question may ask for the tutor’s view, not the student’s.","tr":"Hoca ve öğrenci aynı fikirde olmayabilir. Soru öğrencinin değil hocanın görüşünü sorabilir.","fa":"استاد و دانشجو ممکن است هم‌نظر نباشند. سؤال شاید نظر استاد را بخواهد، نه دانشجو."},{"en":"\"Most useful\" and \"most enjoyable\" are different questions about the same placement.","tr":"\"En faydalı\" ile \"en keyifli\" aynı staj hakkında iki ayrı sorudur.","fa":"«مفیدترین» و «لذت‌بخش‌ترین» دو سؤال متفاوت درباره‌ی همان کارآموزی‌اند."}],"example":{"lines":[["Tutor","What did you get most out of?"],["Student","Well, I loved working with the animals."],["Student","But honestly, the most useful thing was watching how the vets talked to worried owners."]],"item":"What was most useful for the student?  A working with animals   B learning how to talk to owners   C using the equipment","answer":"B","why":{"en":"Working with animals was enjoyable. \"The most useful thing\" was watching the vets talk to owners.","tr":"Hayvanlarla çalışmak keyifliydi. \"En faydalı şey\" veterinerlerin sahiplerle konuşmasını izlemekti.","fa":"کار با حیوان‌ها لذت‌بخش بود. «مفیدترین چیز» دیدن طرز حرف زدن دامپزشک‌ها با صاحبان حیوان بود."}},"general":true,"patterns":["L3-humanities"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Two pairs, then six single choices","tr":"İki çift, sonra altı tek seçim","fa":"دو جفت سؤال، بعد شش سؤال تک‌جوابی"},"body":{"en":"Questions 21-22 and 23-24: choose TWO letters, A-E. Questions 25-30: choose A, B or C. The questions follow the conversation, and there is a pause before Question 25.","tr":"Soru 21-22 ve 23-24: A-E arasından İKİ harf seç. Soru 25-30: A, B ya da C’yi seç. Sorular konuşmayı izler ve Soru 25’ten önce bir ara vardır.","fa":"سؤال‌های ۲۱-۲۲ و ۲۳-۲۴: دو حرف از A تا E انتخاب کن. سؤال‌های ۲۵ تا ۳۰: A، B یا C را انتخاب کن. سؤال‌ها به ترتیب گفتگو می‌آیند و قبل از سؤال ۲۵ یک مکث هست."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Underline who the question is about: \"Callum thinks\", \"they agree\". The other speaker’s view may be different.","tr":"Sorunun kimle ilgili olduğunun altını çiz: \"Callum thinks\", \"they agree\". Diğer konuşanın görüşü farklı olabilir.","fa":"زیر اینکه سؤال درباره‌ی کیست خط بکش: «Callum thinks»، «they agree». نظر گوینده‌ی دیگر ممکن است فرق کند."},{"en":"Expect each option to be mentioned. Wait until one speaker accepts it and the other does not object.","tr":"Her seçenekten söz edilmesini bekle. Bir konuşan kabul edene ve diğeri itiraz etmeyene kadar bekle.","fa":"انتظار داشته باش از همه‌ی گزینه‌ها حرف زده شود. صبر کن تا یکی قبولش کند و دیگری مخالفت نکند."},{"en":"Listen for the turn: but, the trouble was, I don’t think that’s the main thing.","tr":"Dönüşe kulak ver: but, the trouble was, I don’t think that’s the main thing.","fa":"به نقطه‌ی چرخش گوش بده: but، the trouble was، I don’t think that’s the main thing."},{"en":"If you miss one, choose the most likely letter and move to the next question at once.","tr":"Birini kaçırırsan en olası harfi seç ve hemen sonraki soruya geç.","fa":"اگر یکی را از دست دادی، محتمل‌ترین حرف را انتخاب کن و فوراً برو سراغ سؤال بعد."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Words you hear are not the answer","tr":"Duyduğun kelimeler cevap değil","fa":"کلمه‌ای که می‌شنوی جواب نیست"},"table":{"headers":{"en":["You hear","It means"],"tr":["Duyduğun","Anlamı"],"fa":["می‌شنوی","یعنی"]},"rows":[["We all knew that.","not a surprise"],["That takes weeks.","the idea is dropped"],["Some do, but...","not the main reason"],["The trouble was...","the problem comes now"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One single choice, step by step","tr":"Bir tek seçim, adım adım","fa":"یک سؤال تک‌جوابی، قدم به قدم"},"instruction":"Choose the correct letter, A, B or C.","item":"What does the man say about the online quizzes? A They are too easy.  B They help him find gaps in his knowledge.  C They take too long.","lines":[["Man","People say they’re too easy, and some of them are. And yes, they take a while. But each time I do one, I find a topic I thought I knew and didn’t."]],"answer":"B","walk":[{"en":"The question asks what HE says, not what people say.","tr":"Soru insanların ne dediğini değil, ONUN ne dediğini soruyor.","fa":"سؤال می‌پرسد خودِ او چه می‌گوید، نه مردم."},{"en":"A is what \"people say\"; C is admitted but then \"But...\" changes direction.","tr":"A \"insanların dediği\"; C kabul ediliyor ama sonra \"But...\" yönü değiştiriyor.","fa":"A حرفِ «مردم» است؛ C پذیرفته می‌شود، اما بعد «But...» جهت را عوض می‌کند."},{"en":"\"A topic I thought I knew and didn’t\" = gaps in his knowledge: B.","tr":"\"Bildiğimi sandığım ama bilmediğim bir konu\" = bilgisindeki boşluklar: B.","fa":"«موضوعی که فکر می‌کردم بلدم ولی نبودم» یعنی جاهای خالیِ دانسته‌هایش: B."}]},"quick":{"prompt":"\"I know some people find the reading list too long, and I suppose it is. What bothers me more is that half the books aren’t in the library.\" What is her main complaint?","options":["the books are hard to get","the list is too long","the books are out of date"],"correct":0,"why":{"en":"She admits the length, then \"what bothers me more\" gives her main complaint: the books are not in the library.","tr":"Uzunluğu kabul ediyor, sonra \"beni daha çok rahatsız eden\" asıl şikâyetini veriyor: kitaplar kütüphanede yok.","fa":"طولانی بودن را قبول می‌کند، بعد «چیزی که بیشتر اذیتم می‌کند» شکایت اصلی‌اش را می‌گوید: کتاب‌ها در کتابخانه نیستند."}},"remember":{"en":"Check whose opinion the question asks for, and choose the idea that is still standing at the end.","tr":"Sorunun kimin görüşünü sorduğuna bak ve sonda hâlâ ayakta kalan fikri seç.","fa":"ببین سؤال نظر چه کسی را می‌خواهد و ایده‌ای را انتخاب کن که آخر سر هنوز سر جایش است."},"type":"explain","id":"c-x08-l3-e","course":"ielts-exams","exam":"exam-08","unit":"x08-l3"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 3","title":{"en":"An assignment on note-taking","tr":"Not alma üzerine bir ödev","fa":"تکلیفی درباره‌ی یادداشت‌برداری"},"timed":7,"ctx":["L3-humanities"],"script":[{"who":"Esme","line":"So, Callum, have you finished the article on note-taking that Dr Price gave us?"},{"who":"Callum","line":"Yes, last night. Some of it was pretty predictable. Of course people who type their notes write down more words. We all knew that."},{"who":"Esme","line":"And that writing by hand is slower. Nobody needs a study to tell them that. But the memory test was a real surprise for me. The students who'd written by hand could explain the main ideas much better a week later, even though they'd written less."},{"who":"Callum","line":"Same for me. I'd have bet on the typists. The other thing I hadn't expected was the effect on other people. Students sitting near someone with a laptop open did worse in the test, even if they weren't using a laptop themselves."},{"who":"Esme","line":"I'd never thought about the people around you. That's quite a strong argument for a laptop-free row in lecture halls."},{"who":"Callum","line":"So what do we want to put in our assignment? I wondered about a survey of our own year group."},{"who":"Esme","line":"I like the idea, but we'd need ethics approval for a survey, and that takes weeks. We've only got a month."},{"who":"Callum","line":"Fair enough. What about interviewing one of the lecturers?"},{"who":"Esme","line":"Dr Price is away until the end of term, and the others are marking. I don't think we'd get anyone."},{"who":"Callum","line":"OK. So, more realistically, we could compare two note-taking methods: the ordinary linear notes everyone takes and the split-page method from the article, with questions on one side and notes on the other."},{"who":"Esme","line":"Yes, that would give the assignment a clear structure. And we could include examples of our own notes from the same lecture, one in each style, to show the difference."},{"who":"Callum","line":"Good, a comparison plus our own examples. I'd leave out the library statistics on laptop loans, though. They don't really tell us anything about learning."},{"who":"Esme","line":"Agreed."},{"who":"Callum","line":"Right, let's look at the other points Dr Price wants us to discuss. First, lecture slides. Why do you think having the slides makes people take fewer notes?"},{"who":"Esme","line":"Isn't it because they just copy the slides word for word?"},{"who":"Callum","line":"Some do, but I don't think that's the main thing. Most students assume that if the slides are online, they don't need to write anything at all. They sit back and listen, and then they never actually open the slides afterwards."},{"who":"Esme","line":"That's true of half our class. What about recording lectures? I record most of mine."},{"who":"Callum","line":"Do you listen to them again?"},{"who":"Esme","line":"Honestly, not the whole thing. It would take forever. But when there's a part I really didn't understand, like the statistics lecture last week, I go back to that bit before an exam. So for me it's a revision tool for the hard sections, not a replacement for notes."},{"who":"Callum","line":"That makes sense. I tried mind maps last term, by the way, after that study skills workshop."},{"who":"Esme","line":"How did that go? They look great when other people do them."},{"who":"Callum","line":"They were quite quick to draw, actually, and in the lecture they felt really creative. The trouble was afterwards. When I looked at them a month later, I couldn't follow them at all. All the arrows went everywhere, and I couldn't remember what connected to what."},{"who":"Esme","line":"So they're hard to read later. That's a useful point for the assignment. For me, what matters most in note-taking isn't speed. People spend ages learning shorthand and abbreviations, but the real skill is deciding what not to write down. If you try to get everything, you understand nothing."},{"who":"Callum","line":"Choosing what to leave out. I'll write that down, ironically."},{"who":"Esme","line":"And what did you think of the tutor's guidance sheet for the assignment?"},{"who":"Callum","line":"It came out on time, which was good, and it fits the reading. But it's so general. It says things like 'discuss the evidence', without telling us how much detail they want."},{"who":"Esme","line":"Exactly what I thought. It could be about any assignment."},{"who":"Callum","line":"So, what next? Shall we email Dr Price to ask for more detail?"},{"who":"Esme","line":"She's away, remember, and she said she won't answer emails. I think we should just divide up the reading list. You take the studies on memory, and I'll take the ones on distraction, and we meet again on Thursday."},{"who":"Callum","line":"Deal. I'll start this evening."}],"groups":[{"instruction":"Questions 21-22. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":21,"n2":22,"kind":"mcq2","prompt":"Which TWO findings in the article surprised the students?","options":["A how well students who wrote by hand could explain ideas later","B how many more words students wrote when they typed","C how much slower writing by hand is","D how laptops affected students sitting nearby","E how many students preferred to use paper"],"correct":[0,3],"evidence":"the memory test was a real surprise for me","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"A \"the memory test was a real surprise\" and D \"the other thing I hadn’t expected\". B and C are things \"we all knew\"; E is never mentioned.","tr":"A \"hafıza testi gerçek bir sürprizdi\" ve D \"beklemediğim diğer şey\". B ve C \"hepimizin bildiği\" şeyler; E’den hiç söz edilmiyor.","fa":"A «آزمون حافظه واقعاً غافلگیرم کرد» و D «چیز دیگری که انتظارش را نداشتم». B و C چیزهایی‌اند که «همه می‌دانستیم»؛ از E اصلاً حرفی نیست."}}]},{"instruction":"Questions 23-24. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":23,"n2":24,"kind":"mcq2","prompt":"Which TWO things will the students include in their assignment?","options":["A a survey of students in their year","B a comparison of two ways of taking notes","C examples of their own notes","D an interview with a lecturer","E figures on laptop loans from the library"],"correct":[1,2],"evidence":"a comparison plus our own examples","trap":["TR-ruledout"],"why":{"en":"Callum sums up: \"a comparison plus our own examples\". The survey needs approval that takes weeks, no lecturer is free, and the library figures are left out.","tr":"Callum özetliyor: \"bir karşılaştırma artı kendi örneklerimiz\". Anket haftalar süren bir onay ister, boşta hoca yok, kütüphane rakamları da çıkarılıyor.","fa":"کالوم جمع‌بندی می‌کند: «یک مقایسه به‌اضافه‌ی نمونه‌های خودمان». نظرسنجی مجوزی می‌خواهد که هفته‌ها طول می‌کشد، هیچ استادی وقت ندارد و آمار کتابخانه هم کنار گذاشته می‌شود."}}]},{"instruction":"Questions 25-30. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":25,"kind":"mcq","prompt":"According to Callum, why do students take fewer notes when the lecture slides are available?","options":["A They copy the slides word for word.","B They believe taking notes is unnecessary.","C They download the slides before the lecture."],"correct":1,"evidence":"they don't need to write anything at all","why":{"en":"Copying is what Esme suggests; Callum says \"I don’t think that’s the main thing\". They assume they need not write anything.","tr":"Kopyalamak Esme’nin önerisi; Callum \"asıl mesele bu değil bence\" diyor. Hiçbir şey yazmaları gerekmediğini sanıyorlar.","fa":"کپی کردن پیشنهاد اِسمه است؛ کالوم می‌گوید «فکر نمی‌کنم موضوع اصلی این باشد». خیال می‌کنند لازم نیست چیزی بنویسند."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":26,"kind":"mcq","prompt":"What does Esme say about recording lectures?","options":["A She uses the recordings to revise difficult parts.","B She listens to every recording again before exams.","C She has stopped because it takes too long."],"correct":0,"evidence":"it's a revision tool for the hard sections","why":{"en":"She does not listen to \"the whole thing\"; she goes back to the parts she did not understand.","tr":"\"Hepsini\" dinlemiyor; anlamadığı kısımlara geri dönüyor.","fa":"«کل آن را» گوش نمی‌دهد؛ به بخش‌هایی برمی‌گردد که نفهمیده بود."},"trap":["TR-paraphrase"]},{"n":27,"kind":"mcq","prompt":"What problem did Callum have with mind maps?","options":["A They took too long to draw.","B They did not suit the subject of the lecture.","C They were difficult to understand later."],"correct":2,"evidence":"I couldn't follow them at all","why":{"en":"They were \"quite quick to draw\", so A is wrong. \"The trouble was afterwards\": he could not follow them a month later.","tr":"\"Çizmesi oldukça hızlıydı\", yani A yanlış. \"Sorun sonradan çıktı\": bir ay sonra onları takip edemedi.","fa":"«کشیدنشان نسبتاً سریع بود»، پس A غلط است. «مشکل بعدش بود»: یک ماه بعد نمی‌توانست دنبالشان کند."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":28,"kind":"mcq","prompt":"Esme thinks the most important skill in note-taking is","options":["A writing quickly.","B using abbreviations.","C deciding what to leave out."],"correct":2,"evidence":"the real skill is deciding what not to write down","why":{"en":"\"What matters most... isn’t speed\", and shorthand is what \"people spend ages learning\". The real skill: deciding what not to write.","tr":"\"En önemli şey... hız değil\"; kısaltmalar \"insanların uzun uzun öğrendiği\" şey. Asıl beceri: neyi yazmayacağına karar vermek.","fa":"«مهم‌ترین چیز... سرعت نیست» و تندنویسی چیزی است که «مردم مدت‌ها یادش می‌گیرند». مهارت اصلی: تصمیم اینکه چه چیزی را ننویسی."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":29,"kind":"mcq","prompt":"What do the students think of the tutor’s guidance sheet?","options":["A It is too general.","B It was published late.","C It does not match the reading."],"correct":0,"evidence":"But it's so general","why":{"en":"It \"came out on time\" and \"fits the reading\". The problem: \"it’s so general\".","tr":"\"Zamanında çıktı\" ve \"okumalara uyuyor\". Sorun: \"çok genel\".","fa":"«به‌موقع منتشر شد» و «با منابع جور است». مشکل: «خیلی کلی است»."},"trap":["TR-ruledout"]},{"n":30,"kind":"mcq","prompt":"What will the students do next?","options":["A email the tutor","B divide the reading list between them","C arrange a meeting with the librarian"],"correct":1,"evidence":"we should just divide up the reading list","why":{"en":"The tutor \"won’t answer emails\". They divide the reading and meet again on Thursday.","tr":"Hoca \"e-postalara cevap vermeyecek\". Okuma listesini bölüşüp perşembe tekrar buluşuyorlar.","fa":"استاد «به ایمیل‌ها جواب نمی‌دهد». فهرست منابع را تقسیم می‌کنند و پنجشنبه دوباره همدیگر را می‌بینند."},"trap":["TR-ruledout"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Esme":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_emma"},"role":"Student"},"Callum":{"accent":"Scottish","gender":"M","tts":{"engine":"kokoro","voice":"bm_lewis","fallback":true,"note":"Scottish wanted; no clearly licensed free Scottish male voice yet (Piper alan is All Rights Reserved)"},"role":"Student"}},"sequence":[{"type":"announcer","text":"Part 3. You will hear two students, Esme and Callum, discussing an assignment on note-taking. First, you have some time to look at Questions 21 to 24."},{"type":"pause","seconds":30,"note":"reading time, Questions 21-24"},{"type":"announcer","text":"Now listen carefully and answer Questions 21 to 24."},{"type":"sfx","note":"quiet study room, a page turning now and then"},{"type":"lines","from":0,"to":12},{"type":"announcer","text":"Before you hear the rest of the discussion, you have some time to look at Questions 25 to 30."},{"type":"pause","seconds":30,"note":"reading time, Questions 25-30"},{"type":"announcer","text":"Now listen and answer Questions 25 to 30."},{"type":"lines","from":13,"to":29},{"type":"announcer","text":"That is the end of Part 3. You now have half a minute to check your answers.","after":30}]},"id":"c-x08-l3-d","course":"ielts-exams","exam":"exam-08","unit":"x08-l3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Nobody needs a study to tell them that.\" The speaker thinks the finding is...","options":["surprising","wrong","obvious"],"correct":2,"why":{"en":"If you do not need a study to know it, it is obvious.","tr":"Bunu bilmek için bir araştırmaya gerek yoksa apaçıktır.","fa":"اگر برای دانستنش به پژوهش نیازی نیست، یعنی بدیهی است."}},{"tests":"paraphrase","point":3,"prompt":"Which sentence means \"they are hard to read later\"?","options":["They took me ages to finish.","When I looked back, I couldn’t make sense of them.","I didn’t enjoy making them."],"correct":1,"why":{"en":"\"Couldn’t make sense of them\" when looking back = difficult to understand later.","tr":"Geri dönüp baktığında \"anlamlandıramadım\" = sonradan anlaşılması zor.","fa":"«نتوانستم ازشان سر دربیاورم» وقتی دوباره نگاه کردم، یعنی بعداً سخت فهمیده می‌شوند."}},{"tests":"trap","point":3,"prompt":"\"Some students record lectures just to avoid writing, but that’s not why I do it. I use them to check the bits I missed.\" Why does the speaker record lectures?","options":["to check parts she missed","to avoid writing notes","to share them with friends"],"correct":0,"why":{"en":"\"That’s not why I do it\" rules out avoiding writing; her reason follows.","tr":"\"Ben bu yüzden yapmıyorum\" not yazmaktan kaçmayı eliyor; onun nedeni ardından geliyor.","fa":"«من به این دلیل این کار را نمی‌کنم» فرار از نوشتن را رد می‌کند؛ دلیل خودش بعدش می‌آید."}},{"tests":"method","point":2,"prompt":"Question: \"Which TWO things will the students include?\" One suggests a survey, the other says it needs approval that takes weeks. What do you do?","options":["Choose the survey","Wait for the tutor’s view","Cross out the survey"],"correct":2,"why":{"en":"A suggestion that meets a practical objection is dropped. Choose only what they keep.","tr":"Pratik bir itirazla karşılaşan öneri bırakılır. Yalnızca tuttuklarını seç.","fa":"پیشنهادی که با یک اشکال عملی روبه‌رو می‌شود کنار می‌رود. فقط چیزی را انتخاب کن که نگهش می‌دارند."}},{"tests":"method","point":2,"prompt":"A question says \"Esme thinks...\". Callum gives his view first. What do you do?","options":["Choose Callum’s view","Wait for Esme’s view","Choose the view they both mention"],"correct":1,"why":{"en":"The question is about one speaker. The other speaker’s opinion is often a distractor.","tr":"Soru bir konuşanla ilgili. Diğer konuşanın görüşü çoğu zaman çeldiricidir.","fa":"سؤال درباره‌ی یک گوینده است. نظر گوینده‌ی دیگر اغلب گزینه‌ی انحرافی است."}}],"id":"c-x08-l3-x","course":"ielts-exams","exam":"exam-08","unit":"x08-l3"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
